<?php session_start();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$f=fopen(__DIR__.'/users.csv','r');$ok=false;while(($row=fgetcsv($f))!==false){if(count($row)>=3&&$row[0]===$email&&password_verify($pass,$row[1])){$_SESSION['email']=$email;$_SESSION['role']=$row[2];session_regenerate_id(true);$ok=true;break;}}fclose($f);if($ok){header('Location: dashboard.php');exit;}$error='Invalid credentials';} ?><p><?=htmlspecialchars($error)?></p><form method="post"><input name="email" type="email" required><input name="password" type="password" required><button>Login</button></form>